import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.CRfKVJQk.js";const b=JSON.parse('{"title":"09 · Web","description":"How the library runs in a browser: which build is loaded, how glass is drawn, and what server rendering needs.","frontmatter":{"description":"How the library runs in a browser: which build is loaded, how glass is drawn, and what server rendering needs.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/09-web"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/09-web"}],["meta",{"property":"og:title","content":"09 · Web · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"How the library runs in a browser: which build is loaded, how glass is drawn, and what server rendering needs."}],["meta",{"name":"twitter:title","content":"09 · Web · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"How the library runs in a browser: which build is loaded, how glass is drawn, and what server rendering needs."}]]},"headers":[],"relativePath":"architecture/09-web.md","filePath":"architecture/09-web.md"}'),r={name:"architecture/09-web.md"};function o(d,e,n,c,h,l){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="_09-·-web" tabindex="-1">09 · Web <a class="header-anchor" href="#_09-·-web" aria-label="Permalink to &quot;09 · Web&quot;">​</a></h1><p>How the library runs in a browser: which build is loaded, how glass is drawn, and what server rendering needs.</p><h2 id="which-build-the-browser-gets" tabindex="-1">Which build the browser gets <a class="header-anchor" href="#which-build-the-browser-gets" aria-label="Permalink to &quot;Which build the browser gets&quot;">​</a></h2><p><code>package.json</code> exports three entry points for the same public API:</p><table tabindex="0"><thead><tr><th>Export condition</th><th>File</th><th>Used by</th></tr></thead><tbody><tr><td><code>source</code></td><td><code>src/index.ts</code></td><td>Tools that compile the TypeScript source, such as the docs&#39; example type-check</td></tr><tr><td><code>browser</code>, <code>node</code></td><td><code>lib/web/index.js</code></td><td>Vite, webpack, Next.js (client and server), Expo web</td></tr><tr><td><code>default</code></td><td><code>lib/module/index.js</code></td><td>Metro for Android and iOS</td></tr></tbody></table><p>Metro versions that don&#39;t read <code>exports</code> use the <code>react-native</code> field instead, which points to <code>src/index.ts</code>.</p><p><code>lib/web</code> is written by <code>scripts/build-web.js</code> during <code>npm run prepare</code>. It&#39;s a copy of <code>lib/module</code> with one file swapped: <code>native/nativeBridge.js</code> is replaced by <code>native/nativeBridge.web.js</code>. The native bridge is the only module that imports the codegen specs (<code>codegenNativeComponent</code>, <code>TurboModuleRegistry</code>), so after the swap no native code is reachable from the web entry.</p><p>Metro for Expo web gets the same web bridge, through the <code>browser</code> condition or the <code>.web.js</code> file extension.</p><h2 id="the-web-bridge" tabindex="-1">The web bridge <a class="header-anchor" href="#the-web-bridge" aria-label="Permalink to &quot;The web bridge&quot;">​</a></h2><p><code>nativeBridge.web.ts</code> exports the same names as the native bridge, with native turned off:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> isNativeAvailable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nativeModule</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> NativeGlassView</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> NativeBackdrop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>A unit test (<code>src/__tests__/webBridge.test.ts</code>) keeps the two bridges&#39; exports in sync.</p><h2 id="the-css-renderer" tabindex="-1">The CSS renderer <a class="header-anchor" href="#the-css-renderer" aria-label="Permalink to &quot;The CSS renderer&quot;">​</a></h2><p>With no native view, <code>LiquidGlassView</code> renders <code>FallbackGlass</code>, a react-native-web <code>View</code>. On the web it applies:</p><table tabindex="0"><thead><tr><th>Glass value</th><th>CSS</th></tr></thead><tbody><tr><td><code>blur</code> (after <code>intensity</code>)</td><td><code>backdrop-filter: blur(&lt;blur&gt;px) saturate(160%)</code> (and the <code>-webkit-</code> prefix)</td></tr><tr><td><code>tint</code>, <code>tintOpacity</code></td><td><code>background-color</code> with that opacity</td></tr><tr><td><code>borderWidth</code>, <code>borderOpacity</code></td><td>a white border at that opacity</td></tr><tr><td><code>cornerRadius</code></td><td><code>border-radius</code></td></tr><tr><td><code>clipContent</code></td><td><code>overflow: hidden</code></td></tr><tr><td><code>reduceTransparency</code> on</td><td>an opaque <code>fallbackColor</code> background instead of the blur</td></tr></tbody></table><p>Refraction, distortion, chromatic aberration, edge width, the rim light, touch light and tilt lighting have no CSS equivalent, so they&#39;re ignored. <code>GlassBackdrop</code> is a plain <code>View</code>: the browser blurs whatever is painted behind the glass.</p><p><code>useGlassCapabilities()</code> reports <code>platform: &quot;web&quot;</code> and <code>bestRenderer: &quot;fallback&quot;</code> (the docs call this the <strong>CSS renderer</strong>).</p><h2 id="server-rendering" tabindex="-1">Server rendering <a class="header-anchor" href="#server-rendering" aria-label="Permalink to &quot;Server rendering&quot;">​</a></h2><ul><li>Nothing reads <code>window</code>, <code>document</code> or <code>navigator</code> when the package is imported, so Next.js can prerender pages that use it.</li><li>On the server, Next.js resolves the <code>node</code> condition, which also points to <code>lib/web</code>, so the server never touches native code either.</li><li>Components that use hooks must be in a <code>&#39;use client&#39;</code> file, like any client component.</li></ul><p>Verified with Next.js 16 (App Router, Turbopack): <code>next build</code> prerenders the page and the browser hydrates it.</p><h2 id="browser-behaviour-to-know-about" tabindex="-1">Browser behaviour to know about <a class="header-anchor" href="#browser-behaviour-to-know-about" aria-label="Permalink to &quot;Browser behaviour to know about&quot;">​</a></h2><ul><li><code>backdrop-filter</code> blurs what&#39;s painted behind the element. If an ancestor of the glass creates its own backdrop root (for example with <code>opacity</code> below 1, <code>filter</code>, <code>mask</code> or <code>will-change</code>), the glass only blurs content inside that ancestor.</li><li>In a browser without <code>backdrop-filter</code>, the glass keeps its tint and border without the blur.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li><code>src/__tests__/webBridge.test.ts</code> checks the web bridge (see above).</li><li><code>npm run typecheck</code> type-checks every documented example against the library source.</li><li>During the 0.3.0 work, every example scene and copy-paste example was run in a Chromium browser with no page errors. These browser checks aren&#39;t part of CI yet.</li></ul>`,24)])])}const u=t(r,[["render",o]]);export{b as __pageData,u as default};
